// Recovery and replacement of pending edits are one browser transaction.
async function checkpointEdits(server:Snapshot,ignoreRows:string[]=[],choice:'ask'|'local'|'server'='ask',checkpoint?:Journal){
 const previousInert=root.inert;root.inert=true;reconciling=true;
 try{await metaTail;const log=checkpoint??new Journal(owner,server.session.id);if(!log.db)await log.open();const saved=await log.load();const actions=saved.commands;const merged=reconcile(server,actions,ignoreRows,choice);if(choice==='local'&&merged.conflicts.some(c=>server.rows.find(r=>r.id===c.id)?.sealed||!server.rows.some(r=>r.id===c.id)))throw Error('An item is already authorized or no longer available. Your edits are retained; keep the saved values for that item.');const overlay=merged.conflicts.length&&choice==='ask'?reconcile(server,actions,ignoreRows,'local'):merged;const next=new Store(server);next.sequence=Math.max(0,...actions.map(a=>a.seq));
 const archived:Action[]=actions.map(a=>({...a,status:'superseded' as const}));
 if(choice==='ask'&&merged.conflicts.length){
  // Keep original comparison bases for a genuine conflict. Rebasing those bases
  // before the owner's choice would turn a conflicting overwrite into a save.
  const ignored=new Set(ignoreRows),ignoredVariations=new Set(server.rows.filter(r=>ignored.has(r.id)).map(r=>r.variation_id));
  for(const prior of actions.filter(a=>a.status==='pending')){const changes=prior.changes.filter(c=>!ignored.has(c.id)&&!server.rows.find(r=>r.id===c.id)?.removed),defaults=prior.defaults.filter(d=>!ignoredVariations.has(d.variation_id));if(!changes.length&&!defaults.length)continue;archived.push({...structuredClone(prior),id:crypto.randomUUID(),seq:++next.sequence,kind:'REBASE',baseVersion:server.session.version,changes,inverse:prior.inverse.filter(c=>changes.some(v=>v.id===c.id)),defaults,inverseDefaults:prior.inverseDefaults.filter(d=>defaults.some(v=>v.variation_id===d.variation_id))});}
 }else{
  const rowIds=[...new Set([...overlay.changes.map(c=>c.id),...overlay.defaults.map(d=>server.rows.find(r=>r.variation_id===d.variation_id)!.id)])];for(let offset=0;offset<rowIds.length;offset+=100){const group=new Set(rowIds.slice(offset,offset+100));const action=next.action('Worksheet edits',overlay.changes.filter(c=>group.has(c.id)),overlay.defaults.filter(d=>group.has(server.rows.find(r=>r.variation_id===d.variation_id)!.id)),undefined,'REBASE');action.baseVersion=server.session.version;archived.push(action);}
 }
 await log.checkpoint(server,archived,{ackVersion:choice==='ask'&&merged.conflicts.length?server.session.version-1:server.session.version,batch:undefined,needsChoice:choice==='ask'&&merged.conflicts.length>0,view:{...(saved.view??initialView()),selected:(saved.view?.selected??[]).filter(id=>!ignoreRows.includes(id)&&!server.rows.find(r=>r.id===id)?.removed)}});return merged;
 }finally{reconciling=false;root.inert=previousInert;}
}
