async function boot(){try{const context=await api('/api/context');owner=context.owner_id;supplierResolutionEnabled=context.supplier_resolution_enabled===true;inventoryRefreshEnabled=context.inventory_refresh_enabled===true;stores=context.stores;managementPath=context.management_path??'/management';legacyOrdersPath=context.legacy_orders_path;readinessPath=context.readiness_path;quotationEnabled=context.quotation_enabled===true;emailEnabled=context.email_enabled===true;submissionEnabled=context.submission_enabled===true;authorizationEnabled=context.authorization_enabled===true;const drafts=await api('/api/worksheets');let id=location.hash.slice(1);try{id=id||localStorage.getItem('v4-current:'+owner)||'';}catch{}let recovered:Snapshot|undefined;if(id){try{const candidate=await api('/api/worksheets/'+id);if(candidate.session.state==='EDITABLE')recovered=candidate;}catch(error){if(![404,422].includes((error as Error&{status?:number}).status??0))throw error;}}if(!recovered&&drafts.rows[0])recovered=await api('/api/worksheets/'+drafts.rows[0].id);if(recovered)await openWorksheet(recovered);else{const emptyDraft=await api('/api/worksheets',{command_id:crypto.randomUUID(),title:'Purchasing worksheet',calculate:false});location.hash=emptyDraft.session.id;await openWorksheet(emptyDraft);freshDialog();}if(submissionEnabled){submissionWorkflow=new SubmissionWorkflow({api,receive:context.receiving_enabled?async(id)=>{await new ReceivingWorkflow(api,loadInventory).open(id);}:undefined,quotation:quotationEnabled?async(id)=>quotationWorkflow!.openRequest(id):undefined,canAuthorize:()=>authorizationEnabled,current:()=>({session:{...snapshot.session,version},rows:[...store.rows.values()]}),notify,ready:async()=>{finishEditor();if(conflicted)throw Error('Resolve worksheet conflicts before purchasing review.');const start=Date.now();while(pending.length||batch||busy){if(Date.now()-start>30000)throw Error('Save or resolve pending worksheet edits before review.');await new Promise(r=>setTimeout(r,40));}if(conflicted)throw Error('Resolve worksheet conflicts before purchasing review.');},refresh:async()=>{const server=await api('/api/worksheets/'+snapshot.session.id);await metaTail;if(pendingAddition||busy){notify('Authorization recorded. Finish or recover your current edits, then reload to see sealed purchasing decisions.',true);return;}if(pending.length||batch||editor?.editing){conflicted=true;serverConflict=server;showConflict();notify('Authorization recorded. Review your newer local edits against the sealed server state.',true);}else await openWorksheet(server);}});if(quotationEnabled)quotationWorkflow=new QuotationWorkflow({api,owner:()=>owner,canAuthorize:()=>authorizationEnabled,ready:async()=>{finishEditor();if(conflicted||pending.length||batch||busy||pendingAddition)throw Error('Save or resolve current worksheet edits before reviewing vendor quotations.');},notify,authorized:async(result)=>{await submissionWorkflow!.showRecorded(result);}});if(emailEnabled)$('#purchasing-email').onclick=()=>void (emailAttention??=new EmailAttention(api)).open().catch(e=>notify(e.message,true));void submissionWorkflow.recover();}}catch(error){root.innerHTML='<div class="startup-error"><h1>Purchasing workspace</h1><p>'+esc((error as Error).message)+'</p><a href="/login">Owner sign in</a></div>';}}
